// ===== ONBOARDING RULES: every threshold and the stage template live here. No AI. =====
const RULES = {
  stallBusinessDays: 5,       // current stage with no status change for MORE than this = risk flag
  redOverdueBusinessDays: 5,  // current stage overdue by MORE than this = red
};

// Owner "us" = our implementation team, "client" = the customer's team.
const STAGE_TEMPLATE = [
  { key: 'kickoff',     name: 'Kickoff',               owner: 'us',     days: 2 },
  { key: 'tech_access', name: 'Technical access',      owner: 'client', days: 3 },
  { key: 'integration', name: 'Integration installed', owner: 'client', days: 2 },
  { key: 'test_event',  name: 'First test event',      owner: 'us',     days: 2 },
  { key: 'first_value', name: 'First value',           owner: 'client', days: 3 },
  { key: 'training',    name: 'Training',              owner: 'us',     days: 2 },
  { key: 'launch',      name: 'Launch',                owner: 'us',     days: 1 },
  { key: 'handover',    name: 'Handover to CSM',       owner: 'us',     days: 2 },
];
// Extra business days on "Integration installed" for each integration in scope.
const INTEGRATION_DAYS = { api: 4, webhook: 2, sso: 3, csv: 1 };
const KNOWN_INTEGRATIONS = Object.keys(INTEGRATION_DAYS);

// ---- dates: plain ISO strings (YYYY-MM-DD), business days = Monday to Friday ----
const toDate = (iso) => new Date(String(iso).slice(0, 10) + 'T00:00:00Z');
const toIso = (d) => d.toISOString().slice(0, 10);
const isWeekend = (d) => d.getUTCDay() === 0 || d.getUTCDay() === 6;
const addBusinessDays = (iso, n) => {
  const d = toDate(iso);
  while (isWeekend(d)) d.setUTCDate(d.getUTCDate() + 1);
  let left = n;
  while (left > 0) {
    d.setUTCDate(d.getUTCDate() + 1);
    if (!isWeekend(d)) left -= 1;
  }
  return toIso(d);
};
// Business days after `fromIso` up to and including `toIsoDate`. 0 when toIsoDate <= fromIso.
const businessDaysBetween = (fromIso, toIsoDate) => {
  const d = toDate(fromIso);
  const end = toDate(toIsoDate);
  let count = 0;
  while (d < end) {
    d.setUTCDate(d.getUTCDate() + 1);
    if (!isWeekend(d)) count += 1;
  }
  return count;
};
const calendarDaysBetween = (fromIso, toIsoDate) =>
  Math.round((toDate(toIsoDate) - toDate(fromIso)) / 86400000);
const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const prettyDate = (iso) => { const d = toDate(iso); return d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()] + ' ' + d.getUTCFullYear(); };

const parseIntegrations = (value) => {
  const list = Array.isArray(value) ? value : String(value || '').split(/[,;]+/);
  return [...new Set(list.map((v) => String(v).trim().toLowerCase())
    .map((v) => (v.startsWith('csv') ? 'csv' : v))
    .filter(Boolean))];
};

// ---- plan from template ----
function buildPlan(contract) {
  const integrations = parseIntegrations(contract.integrations);
  const unknown = integrations.filter((i) => !KNOWN_INTEGRATIONS.includes(i));
  const csvOnly = integrations.length === 1 && integrations[0] === 'csv';
  const warnings = [];
  if (!integrations.length) warnings.push('No integration in scope');
  if (unknown.length) warnings.push('Unknown integration: ' + unknown.join(', '));

  const stages = [];
  let prevDue = contract.signed_date;
  STAGE_TEMPLATE.forEach((t, i) => {
    let days = t.days;
    let owner = t.owner;
    let name = t.name;
    if (t.key === 'tech_access' && integrations.includes('sso')) days += 1; // identity provider admin needed
    if (t.key === 'integration') {
      days += integrations.reduce((sum, k) => sum + (INTEGRATION_DAYS[k] || 0), 0);
      if (csvOnly) owner = 'us'; // we run the import ourselves; nothing to install on their side
    }
    if (t.key === 'test_event' && csvOnly) name = 'First test import';
    const due = addBusinessDays(prevDue, days);
    stages.push({
      project_id: contract.project_id,
      seq: i + 1,
      stage_key: t.key,
      stage_name: name,
      owner,
      business_days: days,
      planned_start: prevDue,
      due_date: due,
      status: 'not started',
      status_since: contract.signed_date,
      done_on: '',
      note: '',
    });
    prevDue = due;
  });
  const plannedLaunch = stages.find((s) => s.stage_key === 'launch').due_date;
  if (contract.target_launch && plannedLaunch > contract.target_launch) {
    warnings.push('Template plan launches on ' + plannedLaunch + ', after the target ' + contract.target_launch);
  }
  return { integrations, csvOnly, stages, plannedLaunch, warnings };
}

// ---- daily check for one project ----
function checkProject(project, projectStages, today) {
  const stages = [...projectStages].sort((a, b) => Number(a.seq) - Number(b.seq));
  const isDone = (s) => String(s.status) === 'done';
  const current = stages.find((s) => !isDone(s)) || null;
  const flags = [];
  const reminders = [];
  let overdueBd = 0;
  let stalledBd = 0;

  let effectiveDue = null;
  if (current) {
    const prev = stages[stages.indexOf(current) - 1];
    const prevDone = prev && prev.done_on ? String(prev.done_on).slice(0, 10) : '';
    // If the previous stage finished late, this stage still gets its normal number of days.
    // Without this, one late stage would make every later stage "overdue" the day it starts.
    effectiveDue = current.due_date;
    if (prevDone) {
      const rebased = addBusinessDays(prevDone, Number(current.business_days));
      if (rebased > effectiveDue) effectiveDue = rebased;
    }
    // The clock starts at the latest of: its own last status change, the day the previous stage finished.
    const candidates = [current.status_since, prevDone, project.signed_date].filter(Boolean).map((d) => String(d).slice(0, 10));
    const waitingSince = candidates.sort().slice(-1)[0];
    stalledBd = businessDaysBetween(waitingSince, today);
    if (today > effectiveDue) {
      overdueBd = businessDaysBetween(effectiveDue, today);
      const who = current.owner === 'client' ? 'client technical contact (' + (project.tech_contact || 'unknown') + ')' : 'our implementation lead';
      reminders.push({ to: who, owner: current.owner, stage: current.stage_name,
        text: current.stage_name + ' was due on ' + effectiveDue + ' and is ' + overdueBd + ' business day(s) late.' });
      flags.push('overdue');
    }
    if (String(current.status) === 'blocked') {
      flags.push(current.owner === 'client' ? 'blocked by client' : 'blocked on our side');
      if (!flags.includes('overdue')) {
        const who = current.owner === 'client' ? 'client technical contact (' + (project.tech_contact || 'unknown') + ')' : 'our implementation lead';
        reminders.push({ to: who, owner: current.owner, stage: current.stage_name, text: current.stage_name + ' is blocked: ' + (current.note || 'no reason given') + '.' });
      }
    }
    if (stalledBd > RULES.stallBusinessDays) flags.push('stalled');
  }

  // Launch projection: the current stage ends on its due date (or today, if it is late),
  // then each remaining stage up to launch takes its template number of business days.
  const launch = stages.find((s) => s.stage_key === 'launch');
  let projectedLaunch;
  if (launch && isDone(launch)) projectedLaunch = String(launch.done_on).slice(0, 10);
  else {
    const currentEnd = today > effectiveDue ? today : effectiveDue;
    const remaining = stages.filter((s) => Number(s.seq) > Number(current.seq) && Number(s.seq) <= Number(launch.seq))
      .reduce((sum, s) => sum + Number(s.business_days), 0);
    projectedLaunch = addBusinessDays(currentEnd, remaining);
  }
  const launchAtRisk = !(launch && isDone(launch)) && project.target_launch && projectedLaunch > project.target_launch;
  if (launchAtRisk) flags.push('launch at risk');

  let health = 'green';
  if (flags.includes('stalled') || launchAtRisk || overdueBd > RULES.redOverdueBusinessDays) health = 'red';
  else if (flags.includes('overdue') || flags.some((f) => f.startsWith('blocked'))) health = 'yellow';

  // Metrics
  const fv = stages.find((s) => s.stage_key === 'first_value');
  const ttfv = fv && isDone(fv) ? calendarDaysBetween(project.signed_date, fv.done_on) : null;
  const done = stages.filter(isDone);
  const onTime = done.filter((s) => String(s.done_on).slice(0, 10) <= s.due_date);

  return {
    project_id: project.project_id,
    client: project.client,
    check_date: today,
    current_stage: current ? current.stage_name : 'All stages done',
    current_owner: current ? current.owner : '',
    current_status: current ? current.status : 'done',
    current_due: effectiveDue || '',
    overdue_bd: overdueBd,
    stalled_bd: current ? stalledBd : 0,
    flags,
    reminders,
    health,
    projected_launch: projectedLaunch,
    target_launch: project.target_launch,
    launched: Boolean(launch && isDone(launch)),
    ttfv_days: ttfv,
    stages_done: done.length,
    stages_on_time: onTime.length,
    on_time_pct: done.length ? Math.round((onTime.length / done.length) * 100) : null,
  };
}

function portfolioMetrics(results) {
  const ttfvs = results.map((r) => r.ttfv_days).filter((v) => v !== null);
  const done = results.reduce((s, r) => s + r.stages_done, 0);
  const onTime = results.reduce((s, r) => s + r.stages_on_time, 0);
  return {
    projects: results.length,
    avg_ttfv_days: ttfvs.length ? Math.round((ttfvs.reduce((a, b) => a + b, 0) / ttfvs.length) * 10) / 10 : null,
    on_time_pct: done ? Math.round((onTime / done) * 100) : null,
    at_risk: results.filter((r) => r.health === 'red').length,
    watch: results.filter((r) => r.health === 'yellow').length,
    green: results.filter((r) => r.health === 'green').length,
  };
}

// ---- stage update ----
const ALLOWED_STATUSES = ['not started', 'in progress', 'blocked', 'done'];
function applyStageUpdate(update, projectStages, today) {
  const stages = [...projectStages].sort((a, b) => Number(a.seq) - Number(b.seq));
  const status = String(update.status || '').trim().toLowerCase();
  const date = String(update.date || today).slice(0, 10);
  const stage = stages.find((s) => s.stage_key === update.stage_key || s.stage_name.toLowerCase() === String(update.stage_key).toLowerCase());
  if (!stages.length) return { ok: false, error: 'Unknown project ' + update.project_id };
  if (!stage) return { ok: false, error: 'Unknown stage ' + update.stage_key + ' for ' + update.project_id };
  if (!ALLOWED_STATUSES.includes(status)) return { ok: false, error: 'Unknown status ' + update.status };
  if (date > today) return { ok: false, error: 'Date ' + date + ' is in the future' };
  const earlierOpen = stages.filter((s) => Number(s.seq) < Number(stage.seq) && s.status !== 'done');
  if (status === 'done' && earlierOpen.length) {
    return { ok: false, error: stage.stage_name + ' cannot be done while ' + earlierOpen[0].stage_name + ' is still open' };
  }
  if (status === 'blocked' && !String(update.note || '').trim()) {
    return { ok: false, error: 'A blocked stage needs a note saying what blocks it' };
  }
  const updated = { ...stage, status, status_since: date, done_on: status === 'done' ? date : '', note: String(update.note || stage.note || '') };
  const after = stages.map((s) => (s === stage ? updated : s));
  return { ok: true, row_id: stage.id, stage: updated, stages_after: after, handover_due: stage.stage_key === 'launch' && status === 'done' };
}

// ---- handover note to the CSM, built by code from the table ----
function buildHandoverNote(project, stages, today) {
  const sorted = [...stages].sort((a, b) => Number(a.seq) - Number(b.seq));
  const launch = sorted.find((s) => s.stage_key === 'launch');
  const fv = sorted.find((s) => s.stage_key === 'first_value');
  const open = sorted.filter((s) => s.status !== 'done');
  const late = sorted.filter((s) => s.status === 'done' && String(s.done_on).slice(0, 10) > s.due_date);
  const withNotes = sorted.filter((s) => String(s.note || '').trim());
  const ttfv = fv && fv.status === 'done' ? calendarDaysBetween(project.signed_date, fv.done_on) : null;
  const lines = [
    'HANDOVER: ' + project.client + ' (' + project.project_id + ')',
    'State: launched on ' + (launch ? launch.done_on : '?') + ' (target ' + project.target_launch + '). Plan: ' + project.plan + '. Integrations: ' + parseIntegrations(project.integrations).join(', ') + '.',
    'Time to first value: ' + (ttfv === null ? 'not reached' : ttfv + ' days') + '. Stages done late: ' + (late.length ? late.map((s) => s.stage_name).join(', ') : 'none') + '.',
    'Open items: ' + (open.length ? open.map((s) => s.stage_name + ' (' + s.owner + ', due ' + s.due_date + ')').join('; ') : 'none') + '.',
    'Notes from the implementation: ' + (withNotes.length ? withNotes.map((s) => s.stage_name + ': ' + s.note).join('; ') : 'none') + '.',
    'Contacts: technical contact ' + (project.tech_contact || 'unknown') + '.',
    'Next step: CSM sends a welcome email within 2 business days, by ' + addBusinessDays(today, 2) + ', and agrees the first check-in in writing.',
  ];
  return lines.join('\n');
}
// ===== end of rules =====
// ===== DRAFT BRIEFS AND CHECKS. The AI writes words; code decides what may be said and checks it afterwards. =====
const MONTHS_D = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const isoToText = (iso) => { const d = new Date(String(iso).slice(0, 10) + 'T00:00:00Z'); return d.getUTCDate() + ' ' + MONTHS_D[d.getUTCMonth()] + ' ' + d.getUTCFullYear(); };
const whose = (owner) => (owner === 'client' ? 'your team' : 'our team');

// kickoff: the fresh plan, written as on the day the contract was signed.
// weekly_status: the state from the daily check (checkProject), so the email never repeats a stale due date.
function buildBrief(project, stages, kind, today, check) {
  const sorted = [...stages].sort((a, b) => Number(a.seq) - Number(b.seq));
  const allowed = new Set([String(project.target_launch).slice(0, 10)]);
  const base = { project_id: project.project_id, client: project.client, kind, target_launch: isoToText(project.target_launch),
    all_stage_names: sorted.map((s) => s.stage_name) };
  if (kind === 'kickoff') {
    const plannedLaunch = sorted.find((s) => s.stage_key === 'launch').due_date;
    sorted.forEach((s) => allowed.add(String(s.due_date).slice(0, 10)));
    const yourTasks = sorted.filter((s) => s.owner === 'client').slice(0, 2);
    const late = plannedLaunch > String(project.target_launch).slice(0, 10);
    return { ...base, today: String(project.signed_date).slice(0, 10),
      stage_table: sorted.map((s) => '- ' + s.stage_name + ' | owner: ' + whose(s.owner) + ' | due: ' + isoToText(s.due_date)).join('\n'),
      next_stage: sorted[1].stage_name, next_due: isoToText(sorted[1].due_date), next_owner: whose(sorted[1].owner),
      your_tasks: yourTasks.map((s) => s.stage_name + ' (due ' + isoToText(s.due_date) + ')').join('; '),
      your_task_names: yourTasks.map((s) => s.stage_name), not_done_names: [],
      launch_line: 'Planned launch from the template: ' + isoToText(plannedLaunch) + '. Target launch: ' + isoToText(project.target_launch) + '.' +
        (late ? ' The template plan is later than the target, so the target cannot be promised.' : ''),
      must_mention: late ? [isoToText(plannedLaunch)] : [], health: 'green', allowed_dates: [...allowed].sort() };
  }
  const done = sorted.filter((s) => s.status === 'done');
  const open = sorted.filter((s) => s.status !== 'done');
  const current = open[0];
  done.forEach((s) => allowed.add(String(s.done_on).slice(0, 10)));
  allowed.add(check.current_due); allowed.add(check.projected_launch);
  const lateText = check.overdue_bd ? ' | ' + check.overdue_bd + ' business days late' : '';
  const lines = done.map((s) => '- ' + s.stage_name + ' | owner: ' + whose(s.owner) + ' | done on ' + isoToText(s.done_on))
    .concat([ '- ' + current.stage_name + ' | owner: ' + whose(current.owner) + ' | due: ' + isoToText(check.current_due) + ' | status: ' + current.status + lateText + (current.note ? ' (' + current.note + ')' : '') ])
    .concat(open.length > 1 ? ['- Later stages, not started: ' + open.slice(1).map((s) => s.stage_name + ' (' + whose(s.owner) + ')').join(', ')] : []);
  const atRisk = check.flags.includes('launch at risk');
  return { ...base, today,
    stage_table: lines.join('\n'),
    next_stage: current.stage_name, next_due: isoToText(check.current_due), next_owner: whose(current.owner),
    your_tasks: open.filter((s) => s.owner === 'client').slice(0, 2).map((s, i) => s.stage_name + (s === current ? ' (due ' + isoToText(check.current_due) + ')' : ' (later)')).join('; ') || 'none right now',
    your_task_names: open.filter((s) => s.owner === 'client').map((s) => s.stage_name),
    not_done_names: open.map((s) => s.stage_name),
    launch_line: 'Projected launch: ' + isoToText(check.projected_launch) + '. Target launch: ' + isoToText(project.target_launch) + '.' +
      (atRisk ? ' The projected launch is later than the target: say this plainly.' : '') +
      (check.overdue_bd ? ' The current stage is late: do not ask for anything by a date that has passed.' : ''),
    must_mention: atRisk ? [isoToText(check.projected_launch)] : [], health: check.health, allowed_dates: [...allowed].sort() };
}

// ---- checks on the AI text ----
const MONTH_RE = MONTHS_D.join('|');
function datesIn(text, defaultYear) {
  const found = [];
  const pad = (n) => String(n).padStart(2, '0');
  const add = (d, m, y) => found.push((y || defaultYear) + '-' + pad(MONTHS_D.findIndex((x) => x.toLowerCase() === m.toLowerCase()) + 1) + '-' + pad(d));
  let m;
  const dm = new RegExp('\\b(\\d{1,2})(?!\\d)(?:st|nd|rd|th)?\\s+(' + MONTH_RE + ')(?:,?\\s+(\\d{4}))?', 'gi');
  while ((m = dm.exec(text))) add(Number(m[1]), m[2], m[3]);
  const md = new RegExp('\\b(' + MONTH_RE + ')\\s+(\\d{1,2})(?!\\d)(?:st|nd|rd|th)?(?:,?\\s+(\\d{4}))?', 'gi');
  while ((m = md.exec(text))) add(Number(m[2]), m[1], m[3]);
  const iso = /\b(20\d\d)-(\d\d)-(\d\d)\b/g;
  while ((m = iso.exec(text))) found.push(m[0]);
  return [...new Set(found)];
}
const sentences = (text) => text.split(/(?<=[.!?])\s+|\n+/).map((s) => s.trim()).filter(Boolean);
const OUR_WORK = /\b(we|we'll|we will|our team|i|i'll|i will)\b[^.?!]{0,60}\b(build|develop|write|code|configure|set up|install|integrate|implement|export|prepare|handle|take care of|do)\b/i;
const FREE = /\b(free|free of charge|at no (extra |additional )?cost|no charge|complimentary|on us|discount)\b/i;
const PROMISE = /\b(guarantee|guaranteed|promise|we commit|on your behalf|whatever it takes)\b/i;

function checkDraft(brief, subject, body) {
  const flags = [];
  const text = subject + '\n' + body;
  const year = brief.today.slice(0, 4);
  const allowed = new Set(brief.allowed_dates);
  const unknown = datesIn(text, year).filter((d) => !allowed.has(d));
  if (unknown.length) flags.push('date not in the plan: ' + unknown.join(', '));
  const lower = text.toLowerCase();
  if (brief.next_stage && !lower.includes(brief.next_stage.toLowerCase())) flags.push('next stage missing: ' + brief.next_stage);
  if (brief.next_due && !lower.includes(brief.next_due.toLowerCase().replace(/ \d{4}$/, ''))) flags.push('next due date missing: ' + brief.next_due);
  brief.not_done_names.forEach((name) => {
    const re = new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + "[^.?!]{0,40}\\b(is|was|has been|have been)\\s+(done|complete|completed|finished|live)\\b", 'i');
    if (re.test(text)) flags.push('says an open stage is done: ' + name);
  });
  sentences(text).forEach((s) => {
    const mentionsClientTask = brief.your_task_names.some((n) => s.toLowerCase().includes(n.toLowerCase()));
    if (mentionsClientTask && OUR_WORK.test(s) && !/\byou(r)?\b/i.test(s)) flags.push('client task described as our work: "' + s.slice(0, 80) + '"');
    if (mentionsClientTask && OUR_WORK.test(s) && /\b(for you|your behalf|instead of you)\b/i.test(s)) flags.push('offers to do the client task: "' + s.slice(0, 80) + '"');
  });
  // Added after reading the first 10 drafts by hand (see README):
  const deadlineRe = new RegExp('\\b(by|before|until|no later than)\\s+((?:\\d{1,2}\\s+(?:' + MONTH_RE + ')(?:\\s+\\d{4})?)|(?:(?:' + MONTH_RE + ')\\s+\\d{1,2}(?:,?\\s+\\d{4})?))', 'gi');
  let dl;
  while ((dl = deadlineRe.exec(text))) datesIn(dl[2], year).filter((d) => d < brief.today).forEach((d) => flags.push('asks for something by a date that has passed: ' + d));
  if (brief.health !== 'green' && /\b(on schedule|on track|going to plan|everything is (fine|good|going well)|still on target|remains? on target)\b/i.test(text)) flags.push('says on track while health is ' + brief.health);
  (brief.must_mention || []).forEach((d) => { if (!lower.includes(d.toLowerCase().replace(/ \d{4}$/, ''))) flags.push('realistic launch date missing: ' + d); });
  if (FREE.test(text)) flags.push('free work or discount');
  if (PROMISE.test(text)) flags.push('promise or guarantee');
  if (!body.trim().startsWith('Hi [CLIENT] team,')) flags.push('unexpected greeting');
  if (!/Implementation team\s*$/.test(body.trim())) flags.push('sign-off missing');
  const words = body.trim().split(/\s+/).length;
  if (words > 190) flags.push('too long: ' + words + ' words');
  return flags;
}
// ===== end of draft rules =====

// Code decides which email each project gets and exactly which facts it may use.
const input = $('Simulated today').first().json;
const today = String(input.today || '').slice(0, 10) || $now.setZone('Europe/Warsaw').toFormat('yyyy-MM-dd');
const evalRun = input.eval_run === true;
const projects = evalRun ? input.eval_projects : $('Get projects').all().map((i) => i.json).filter((p) => p.project_id);
const stages = evalRun ? input.eval_stages : $input.all().map((i) => i.json).filter((s) => s.project_id);
const out = [];
projects.filter((p) => String(p.signed_date).slice(0, 10) <= today).forEach((p) => {
  const st = stages.filter((s) => s.project_id === p.project_id);
  const launch = st.find((s) => s.stage_key === 'launch');
  if (!launch || launch.status === 'done') return; // launched projects get the handover note instead
  const kickoff = st.find((s) => s.stage_key === 'kickoff');
  const kinds = input.draft_mode === 'both' ? ['kickoff', 'weekly_status'] : [kickoff && kickoff.status !== 'done' ? 'kickoff' : 'weekly_status'];
  const check = checkProject(p, st, today); // same rules as OT Daily Check, so the email matches the dashboard
  kinds.forEach((kind) => out.push({ json: { ...buildBrief(p, st, kind, today, check), eval_run: evalRun } }));
});
if (out.length && evalRun) out[0].json.eval_canaries = input.eval_canaries || [];
return out;

// ===== DRAFT BRIEFS AND CHECKS. The AI writes words; code decides what may be said and checks it afterwards. =====
const MONTHS_D = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const isoToText = (iso) => { const d = new Date(String(iso).slice(0, 10) + 'T00:00:00Z'); return d.getUTCDate() + ' ' + MONTHS_D[d.getUTCMonth()] + ' ' + d.getUTCFullYear(); };
const whose = (owner) => (owner === 'client' ? 'your team' : 'our team');

// kickoff: the fresh plan, written as on the day the contract was signed.
// weekly_status: the state from the daily check (checkProject), so the email never repeats a stale due date.
function buildBrief(project, stages, kind, today, check) {
  const sorted = [...stages].sort((a, b) => Number(a.seq) - Number(b.seq));
  const allowed = new Set([String(project.target_launch).slice(0, 10)]);
  const base = { project_id: project.project_id, client: project.client, kind, target_launch: isoToText(project.target_launch),
    all_stage_names: sorted.map((s) => s.stage_name) };
  if (kind === 'kickoff') {
    const plannedLaunch = sorted.find((s) => s.stage_key === 'launch').due_date;
    sorted.forEach((s) => allowed.add(String(s.due_date).slice(0, 10)));
    const yourTasks = sorted.filter((s) => s.owner === 'client').slice(0, 2);
    const late = plannedLaunch > String(project.target_launch).slice(0, 10);
    return { ...base, today: String(project.signed_date).slice(0, 10),
      stage_table: sorted.map((s) => '- ' + s.stage_name + ' | owner: ' + whose(s.owner) + ' | due: ' + isoToText(s.due_date)).join('\n'),
      next_stage: sorted[1].stage_name, next_due: isoToText(sorted[1].due_date), next_owner: whose(sorted[1].owner),
      your_tasks: yourTasks.map((s) => s.stage_name + ' (due ' + isoToText(s.due_date) + ')').join('; '),
      your_task_names: yourTasks.map((s) => s.stage_name), not_done_names: [],
      launch_line: 'Planned launch from the template: ' + isoToText(plannedLaunch) + '. Target launch: ' + isoToText(project.target_launch) + '.' +
        (late ? ' The template plan is later than the target, so the target cannot be promised.' : ''),
      must_mention: late ? [isoToText(plannedLaunch)] : [], health: 'green', allowed_dates: [...allowed].sort() };
  }
  const done = sorted.filter((s) => s.status === 'done');
  const open = sorted.filter((s) => s.status !== 'done');
  const current = open[0];
  done.forEach((s) => allowed.add(String(s.done_on).slice(0, 10)));
  allowed.add(check.current_due); allowed.add(check.projected_launch);
  const lateText = check.overdue_bd ? ' | ' + check.overdue_bd + ' business days late' : '';
  const lines = done.map((s) => '- ' + s.stage_name + ' | owner: ' + whose(s.owner) + ' | done on ' + isoToText(s.done_on))
    .concat([ '- ' + current.stage_name + ' | owner: ' + whose(current.owner) + ' | due: ' + isoToText(check.current_due) + ' | status: ' + current.status + lateText + (current.note ? ' (' + current.note + ')' : '') ])
    .concat(open.length > 1 ? ['- Later stages, not started: ' + open.slice(1).map((s) => s.stage_name + ' (' + whose(s.owner) + ')').join(', ')] : []);
  const atRisk = check.flags.includes('launch at risk');
  return { ...base, today,
    stage_table: lines.join('\n'),
    next_stage: current.stage_name, next_due: isoToText(check.current_due), next_owner: whose(current.owner),
    your_tasks: open.filter((s) => s.owner === 'client').slice(0, 2).map((s, i) => s.stage_name + (s === current ? ' (due ' + isoToText(check.current_due) + ')' : ' (later)')).join('; ') || 'none right now',
    your_task_names: open.filter((s) => s.owner === 'client').map((s) => s.stage_name),
    not_done_names: open.map((s) => s.stage_name),
    launch_line: 'Projected launch: ' + isoToText(check.projected_launch) + '. Target launch: ' + isoToText(project.target_launch) + '.' +
      (atRisk ? ' The projected launch is later than the target: say this plainly.' : '') +
      (check.overdue_bd ? ' The current stage is late: do not ask for anything by a date that has passed.' : ''),
    must_mention: atRisk ? [isoToText(check.projected_launch)] : [], health: check.health, allowed_dates: [...allowed].sort() };
}

// ---- checks on the AI text ----
const MONTH_RE = MONTHS_D.join('|');
function datesIn(text, defaultYear) {
  const found = [];
  const pad = (n) => String(n).padStart(2, '0');
  const add = (d, m, y) => found.push((y || defaultYear) + '-' + pad(MONTHS_D.findIndex((x) => x.toLowerCase() === m.toLowerCase()) + 1) + '-' + pad(d));
  let m;
  const dm = new RegExp('\\b(\\d{1,2})(?!\\d)(?:st|nd|rd|th)?\\s+(' + MONTH_RE + ')(?:,?\\s+(\\d{4}))?', 'gi');
  while ((m = dm.exec(text))) add(Number(m[1]), m[2], m[3]);
  const md = new RegExp('\\b(' + MONTH_RE + ')\\s+(\\d{1,2})(?!\\d)(?:st|nd|rd|th)?(?:,?\\s+(\\d{4}))?', 'gi');
  while ((m = md.exec(text))) add(Number(m[2]), m[1], m[3]);
  const iso = /\b(20\d\d)-(\d\d)-(\d\d)\b/g;
  while ((m = iso.exec(text))) found.push(m[0]);
  return [...new Set(found)];
}
const sentences = (text) => text.split(/(?<=[.!?])\s+|\n+/).map((s) => s.trim()).filter(Boolean);
const OUR_WORK = /\b(we|we'll|we will|our team|i|i'll|i will)\b[^.?!]{0,60}\b(build|develop|write|code|configure|set up|install|integrate|implement|export|prepare|handle|take care of|do)\b/i;
const FREE = /\b(free|free of charge|at no (extra |additional )?cost|no charge|complimentary|on us|discount)\b/i;
// A denial ("we cannot promise") is honest, so it is not a promise.
const PROMISE = /(?<!\b(?:cannot|can't|can not|not|never|won't)\s)\b(guarantee|guaranteed|promise|we commit|on your behalf|whatever it takes)\b/i;

function checkDraft(brief, subject, body) {
  const flags = [];
  const text = subject + '\n' + body;
  const year = brief.today.slice(0, 4);
  const allowed = new Set(brief.allowed_dates);
  const unknown = datesIn(text, year).filter((d) => !allowed.has(d));
  if (unknown.length) flags.push('date not in the plan: ' + unknown.join(', '));
  const lower = text.toLowerCase();
  if (brief.next_stage && !lower.includes(brief.next_stage.toLowerCase())) flags.push('next stage missing: ' + brief.next_stage);
  if (brief.next_due && !lower.includes(brief.next_due.toLowerCase().replace(/ \d{4}$/, ''))) flags.push('next due date missing: ' + brief.next_due);
  brief.not_done_names.forEach((name) => {
    const re = new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + "[^.?!]{0,40}\\b(is|was|has been|have been)\\s+(done|complete|completed|finished|live)\\b", 'i');
    if (re.test(text)) flags.push('says an open stage is done: ' + name);
  });
  sentences(text).forEach((s) => {
    const mentionsClientTask = brief.your_task_names.some((n) => s.toLowerCase().includes(n.toLowerCase()));
    if (mentionsClientTask && OUR_WORK.test(s) && !/\byou(r)?\b/i.test(s)) flags.push('client task described as our work: "' + s.slice(0, 80) + '"');
    if (mentionsClientTask && OUR_WORK.test(s) && /\b(for you|your behalf|instead of you)\b/i.test(s)) flags.push('offers to do the client task: "' + s.slice(0, 80) + '"');
  });
  // Added after reading the first 10 drafts by hand (see README):
  const deadlineRe = new RegExp('\\b(by|before|until|no later than)\\s+((?:\\d{1,2}\\s+(?:' + MONTH_RE + ')(?:\\s+\\d{4})?)|(?:(?:' + MONTH_RE + ')\\s+\\d{1,2}(?:,?\\s+\\d{4})?))', 'gi');
  let dl;
  while ((dl = deadlineRe.exec(text))) datesIn(dl[2], year).filter((d) => d < brief.today).forEach((d) => flags.push('asks for something by a date that has passed: ' + d));
  if (brief.health !== 'green' && /\b(on schedule|on track|going to plan|everything is (fine|good|going well)|still on target|remains? on target)\b/i.test(text)) flags.push('says on track while health is ' + brief.health);
  (brief.must_mention || []).forEach((d) => { if (!lower.includes(d.toLowerCase().replace(/ \d{4}$/, ''))) flags.push('realistic launch date missing: ' + d); });
  // Added after run 4: a draft said the launch "will be later than target" when the projection was 9 days early.
  const launchLate = (brief.must_mention || []).length > 0;
  if (!launchLate && /\b(later than (the |your |our )?target|after (the |your |our )?target|miss(es|ing)? (the |your |our )?target|launch (will be|is) (late|delayed))/i.test(text)) flags.push('says the launch is late when the projection meets the target');
  if (FREE.test(text)) flags.push('free work or discount');
  if (PROMISE.test(text)) flags.push('promise or guarantee');
  if (!body.trim().startsWith('Hi [CLIENT] team,')) flags.push('unexpected greeting');
  if (!/Implementation team\s*$/.test(body.trim())) flags.push('sign-off missing');
  const words = body.trim().split(/\s+/).length;
  if (words > 190) flags.push('too long: ' + words + ' words');
  return flags;
}
// ===== end of draft rules =====

// Every draft is checked by code before a person sees it. A failed check does not delete the draft; it marks it.
const briefs = $('Build draft briefs').all().map((i) => i.json);
const createdAt = $now.setZone('Europe/Warsaw').toFormat('yyyy-MM-dd HH:mm');
const parse = (item) => {
  if (item.error) return { error: 'AI call failed after retries' };
  const text = (item.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('\n').replace(/```json|```/g, '').trim();
  try { return JSON.parse(text); } catch (e) { return { error: 'AI result is not valid JSON' }; }
};
const result = (brief, subject, body, flags, extra) => ({ json: {
  created_at: createdAt, project_id: brief.project_id, kind: brief.kind,
  subject: subject.split('[CLIENT]').join(brief.client), body: body.split('[CLIENT]').join(brief.client),
  check_passed: flags.length === 0, check_notes: flags.length ? flags.join(' | ') : 'All checks passed',
  review_status: 'pending review', reviewer_note: '', eval_run: brief.eval_run, ...extra } });

const rows = $input.all().map((item, i) => {
  const brief = briefs[i];
  const r = parse(item.json);
  if (r.error) return result(brief, '', '', ['NO DRAFT: ' + r.error], { is_canary: false });
  const subject = String(r.subject || '').trim();
  const body = String(r.body || '').trim();
  return result(brief, subject, body, checkDraft(brief, subject, body), { is_canary: false });
});

// Test only: hand-written bad drafts that the checks must catch.
(briefs[0] && briefs[0].eval_canaries || []).forEach((c) => {
  const brief = briefs.find((b) => b.project_id === c.project_id && b.kind === c.kind);
  rows.push(result(brief, c.subject, c.body, checkDraft(brief, c.subject, c.body), { is_canary: true, canary_id: c.id, expect: c.expect, what: c.what }));
});
return rows;
